#pragma once
// Fixed-capacity MPMC queue guarded by a mutex and two condition variables.
// Correct-first baseline for the concurrent market-data project; the project
// later replaces this with a lock-free ring and measures the difference.
//
// Semantics:
//   - push() blocks while full; after close() it drops the value (no-op).
//   - pop() blocks while empty; returns false once closed AND drained.
//   - close() must be called (once) before destroying the queue while any
//     thread might still be waiting.

#include <condition_variable>
#include <cstddef>
#include <mutex>
#include <stdexcept>
#include <utility>
#include <vector>

namespace md {

template <typename T>
class BoundedQueue {
public:
    explicit BoundedQueue(std::size_t capacity) : buf_(capacity) {
        if (capacity == 0) throw std::invalid_argument("capacity must be > 0");
    }

    void push(T value) {
        std::unique_lock<std::mutex> lk(m_);
        not_full_.wait(lk, [&] { return closed_ || size_ < buf_.size(); });
        if (closed_) return;
        buf_[(head_ + size_) % buf_.size()] = std::move(value);
        ++size_;
        not_empty_.notify_one();
    }

    // Returns false once the queue is closed and drained.
    bool pop(T& out) {
        std::unique_lock<std::mutex> lk(m_);
        not_empty_.wait(lk, [&] { return size_ > 0 || closed_; });
        if (size_ == 0) return false;   // closed and drained
        out = std::move(buf_[head_]);
        head_ = (head_ + 1) % buf_.size();
        --size_;
        not_full_.notify_one();
        return true;
    }

    void close() {
        {
            std::lock_guard<std::mutex> lk(m_);
            closed_ = true;
        }
        not_empty_.notify_all();
        not_full_.notify_all();
    }

private:
    std::mutex m_;
    std::condition_variable not_empty_;
    std::condition_variable not_full_;
    std::vector<T> buf_;
    std::size_t head_ = 0;
    std::size_t size_ = 0;
    bool closed_ = false;
};

}  // namespace md

